-- Source: USCIS Immigration and Citizenship Data (3204 rows)
-- Generated by gen_mart_models.py

-- DEDUP (2026-08-18 verification): this mart is a portal crawl of the USCIS
-- reports index (report title + xlsx download link), not extracted statistics --
-- every substantive stat column (CATEGORY, COUNTRY, RECEIPTS, APPROVALS, DENIALS,
-- PENDING, etc.) is 100% blank on every duplicate row. The crawler re-logged the
-- same report-file link up to 561x. Confirm query showed a SINGLE load run
-- (1 distinct _SOURCE_RUN_ID) and the 3,027-row surplus is fully accounted for by
-- 72 exact-duplicate groups (live: 3,204 rows / 177 distinct) -- single-load
-- duplication, exact dups carry no information. Even after this dedup the 177
-- surviving rows are still just catalog links, not real immigration statistics --
-- no numeric content was ever extracted from the linked xlsx files.
with source as (
    select * from {{ source('ripple_raw', 'FED_USCIS_DATA') }}
    qualify row_number() over (
        partition by FORM_NUMBER, FORM_TITLE, FISCAL_YEAR, QUARTER, CATEGORY,
                     COUNTRY, USCIS_OFFICE, RECEIPTS, APPROVALS, DENIALS, PENDING,
                     AVG_PROCESSING_TIME_DAYS, RFE_COUNT, REPORT_TITLE,
                     PUBLICATION_DATE, SOURCE_FILE_URL
        order by _INGESTED_AT) = 1
)

select
    FORM_NUMBER as form_number,
    FORM_TITLE as form_title,
    try_to_number(FISCAL_YEAR) as fiscal_year,
    QUARTER as quarter,
    CATEGORY as category,
    COUNTRY as country,
    USCIS_OFFICE as uscis_office,
    RECEIPTS as receipts,
    APPROVALS as approvals,
    DENIALS as denials,
    PENDING as pending,
    AVG_PROCESSING_TIME_DAYS as avg_processing_time_days,
    try_to_number(RFE_COUNT) as rfe_count,
    REPORT_TITLE as report_title,
    try_to_date(PUBLICATION_DATE) as publication_date,
    SOURCE_FILE_URL as source_file_url
from source
